L20_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_EVENT_PASS_38"
L21_1 = "Un cadre incarnant une v\195\169ritable ic\195\180ne de confiance, fiable au premier regard.\n\195\137quipez-le dans votre profil pour afficher la puissance de votre entreprise."
L19_1[1] = L20_1
