L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_1_2"
L23_1 = "Les Effets du Contremonde sont le reflet de nos anxi\195\169t\195\169s, un principe qui a longtemps \195\169t\195\169 exploit\195\169 par des organisations ne craignant pas de briser les tabous.\nSaviez-vous que certains b\195\162timents sont con\195\167us avec des pi\195\168ces sans portes ? Quand on veut \195\169tablir un repaire \195\160 l'abri des regards, Il suffit de propager de fausses rumeurs et de saupoudrer le tout de quelques Rayon de Corruptions.\nUne pratique bien connue de la Soci\195\169t\195\169, \195\160 n'en pas douter."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_4_1_HM"
L24_1 = "Les corrompus implorent la mis\195\169ricorde tout en d\195\169chirant la chair avec leurs mains."
L22_1[1] = L23_1
L22_1[2] = L24_1
