L25_1 = "SI_UNIT_SKILL_DESC_ESPR_S_DOCTOR_PASSIVE_LV1"
L26_1 = "Les Attaques de base soignent les alli\195\169s \195\160 port\195\169e pour 2 % de leurs PV."
