L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_1_1"
L40_1 = "Quand un pr\195\169dateur accepte de vous donner sa proie, c'est une marque d'affection non n\195\169gligeable."
L38_1[1] = L39_1
L38_1[2] = L40_1
