L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_5_1_3"
L45_1 = "Si vous sentez une pr\195\169sence, ne paniquez pas. Ce n'est rien d'autre que les cris bruissants des feuilles mortes qu'on pi\195\169tine."
L43_1[1] = L44_1
L43_1[2] = L45_1
