L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_2"
L11_1 = "Quand on s'aventure dans un r\195\170ve, on entre au contact de choses qu'on aurait pr\195\169f\195\169r\195\169 ignorer. Les choses qui perturbent le sommeil des r\195\170veurs, o\195\185 encore les r\195\170ves qu'ils font quand ils sont \195\169veill\195\169s..."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_LIFETIME_3"
L12_1 = "Des monstres effrayants vivent \195\160 l'int\195\169rieur des r\195\170ves. Mais pour \195\170tre honn\195\170te, je pr\195\169f\195\168re encore \195\167a. Imagine que j'y rencontre des personnes endormies \195\160 la place ! Qui est-ce que je devrais vaincre alors, le r\195\170veur ou celui dont il r\195\170ve ?"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE@AB_UI_UNIT_VOICE_NKM_UNIT_DREAM_C_NIGHTMARE_LOBBY_TOUCH_NORMAL_4"
L13_1 = "Je chasse les monstres dans les r\195\170ves et toi, dans la r\195\169alit\195\169. La moindre des choses que je puisse faire, c'est de prendre soin de toi dans le domaine des songes pour que tu dormes bien cette nuit."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
