L2_1 = "SI_SKIN_DESC_NKM_UNIT_CA_YOO_MI_NA_1BIRTHDAY"
L3_1 = "Malgr\195\169 les \195\169preuves, elle est rest\195\169e fid\195\168le \195\160 elle-m\195\170me.\nElle sait maintenant ce pour quoi elle est destin\195\169e.\nCependant, elle semble ignorer comment s'amuser.\nSa sup\195\169rieure saura s\195\187rement la conseiller sur ce point.\n\n<color=#ffd34c>Oh, pardon. J'ai vu que tout le monde se donnait la main. Je me suis dit que je devrais faire pareil.</color>"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_BATTLE_MIYA_DONATION_EXT_11"
L4_1 = "Elle a r\195\169ussi"
L2_1[1] = L3_1
