L3_1 = {}
L4_1 = "SI_UNIT_SKILL_DESC_MAID_C_SPEAR_PASSIVE_LV1"
L5_1 = "Elle aime quand \195\167a pique au combat comme dans son assiette. Elle inflige 15\194\160% de d\195\169g\195\162ts suppl\195\169mentaires aux attaquants."
L3_1[1] = L4_1
L3_1[2] = L5_1
