L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_UNIT_SKILL_DESC_S_HB_CHOIENA_PASSIVE_LV1"
L8_1 = "Elle est d\195\169ploy\195\169e pr\195\168s du vaisseau et y reste. Chaque attaque de base augmente sa h\195\162te de 6\194\160%, dans la limite de 30\194\160%."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_XMAS_1_3"
L9_1 = "Elle a \195\169t\195\169 pouss\195\169e \195\160 bout et a fini par sortir de ses gonds, ce qui l'a rendue encore plus suspecte."
L7_1[1] = L8_1
L7_1[2] = L9_1
