L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_C_FREEDOM_LEE_MINSEO@AB_UI_UNIT_VOICE_NKM_UNIT_C_FREEDOM_LEE_MINSEO_LOBBY_TOUCH_NORMAL_2"
