L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_3"
L10_1 = "Extrait de l'article publi\195\169 par Task Planet le 7\194\160mars\n\194\171\194\160Sans soutien financier, l'\195\169quipement s'est d\195\169t\195\169rior\195\169 et les soldats sont partis les uns apr\195\168s les autres. Une baisse des r\195\169sultats s'est accompagn\195\169e de nouvelles coupes budg\195\169taires.\nLes dirigeants de Daymine cherchent toujours \195\160 r\195\169duire leurs co\195\187ts \195\160 tout prix.\194\160\194\187"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_2"
L11_1 = "Extrait de l'article publi\195\169 par Task Planet le 7\194\160mars\n\194\171\194\160Les compagnies TASKFORCE sont extr\195\170mement d\195\169pendantes de leurs ressources et de leur \195\169quipement.\nLes dirigeants de Daymine ont cependant r\195\169alis\195\169 des coupes drastiques dans leur budget, pour soi-disant s'assurer de l'efficacit\195\169 de leurs hommes.\194\160\194\187"
L9_1[1] = L10_1
