L50_1 = "SI_BOSS_DESC_02"
L51_1 = "Une arme gigantesque d'origine inconnue provenant d'une autre dimension. Sp\195\169cialis\195\169e dans la soumission des ennemis \195\160 distance, elle est \195\169galement capable de faire des sauts dimensionnels sans assistance gr\195\162ce \195\160 un syst\195\168me de propulsion similaire \195\160 celui d'un vaisseau dimensionnel.\n\nIl se peut qu'elle ait \195\169t\195\169 programm\195\169e \195\160 l'origine pour faire des allers-retours dans le Contremonde et chasser les O.C., mais au moment o\195\185 elle a \195\169t\195\169 d\195\169couverte, elle \195\169tait hors de contr\195\180le et irr\195\169m\195\169diablement endommag\195\169e par les rayons de corruption.\n\n<color=#FFCF3B>\226\128\187 Le mod\195\169rateur re\195\167oit des dommages suppl\195\169mentaires lorsqu'il est attaqu\195\169 par derri\195\168re, o\195\185 il est vuln\195\169rable.</color>"
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_BOSS_DESC_01"
L52_1 = "Une arme gigantesque d'origine inconnue provenant d'une autre dimension. Sp\195\169cialis\195\169e dans la pulv\195\169risation des ennemis en approche, elle est \195\169galement capable de faire des sauts dimensionnels sans assistance gr\195\162ce \195\160 un syst\195\168me de propulsion similaire \195\160 celui d'un vaisseau dimensionnel.\n\nIl se peut qu'elle ait \195\169t\195\169 programm\195\169e \195\160 l'origine pour faire des allers-retours dans le Contremonde et chasser les O.C., mais au moment o\195\185 elle a \195\169t\195\169 d\195\169couverte, elle \195\169tait hors de contr\195\180le et irr\195\169m\195\169diablement endommag\195\169e par les rayons de corruption.\n\n<color=#FFCF3B>\226\128\187 Le mod\195\169rateur re\195\167oit des dommages suppl\195\169mentaires lorsqu'il est attaqu\195\169 par derri\195\168re, o\195\185 il est vuln\195\169rable.</color>"
