L29_1 = "SI_SKIN_DESC_NKM_UNIT_C_JAPAN_SETSUNA_CHANGE"
L30_1 = "Il y a longtemps, \195\160 l'\195\169poque o\195\185 les gens vivaient en harmonie, cette danseuse \195\169tait au service d'un serpent.\nMais la cr\195\169ature a finalement tourn\195\169 le dos aux humains, agac\195\169e par leur avidit\195\169.\nLa danseuse s'est alors d\195\169cid\195\169e de l'affronter car du sang d'\195\170tre humain coulait dans ses veines.\nMais que se serait-il pass\195\169 si elle avait continu\195\169 \195\160 prot\195\169ger ce serpent ?\n\n<color=#ffd34c>Venez par ici, le serpent vous appelle.</color>"
L28_1[1] = L29_1
L28_1[2] = L30_1
