L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_SKIN_DESC_NKM_UNIT_ACADEMY_C_TWINTAIL_CHANGE"
L34_1 = "Et si Naielle devenait la pr\195\169sidente du Conseil des \195\169l\195\168ves ? \nApparemment elle s'est encore fait battre par Lanchester aujourd'hui, n'est-ce pas ?\nElle pense que cette place est destin\195\169e au plus fort de l'acad\195\169mie.\nEnfin, de toute fa\195\167on elle serait capable de croire que sa tenue repr\195\169sente la Pr\195\169sente du Conseil des \195\169l\195\168ves.\n\n<color=#ffd34c>Pfff, tu n'y connais rien. Tu ne sais pas qu'il est de bon sens qu'une pr\195\169sidente du Conseil des \195\169l\195\168ves s'habille de cette mani\195\168re ?</color>"
L32_1[1] = L33_1
L32_1[2] = L34_1
