L27_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_01_02"
L28_1 = "Un <COLOR=#FFBC00>grand nombre d'O.C.</COLOR> \195\160 vitesse \195\169lev\195\169e font leur apparition apr\195\168s le d\195\169but du raid."
L26_1[1] = L27_1
