L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_OZ_1_1"
L30_1 = "Je n'ai jamais cess\195\169 de regarder les informations \195\160 la t\195\169l\195\169vision et dans les journaux. Mais avec le temps, on parlait de moins en moins de toi. Mais j'ai continu\195\169 \195\160 penser \195\160 toi tous les jours, pour ne pas t'oublier."
L28_1[1] = L29_1
L28_1[2] = L30_1
