L32_1 = "SI_ITEM_DESC_IQI_EQUIP_MAID_S_LEADER_ACC"
L33_1 = "Une ceinture militaire polyvalente qui permet de manipuler toutes sortes d'accessoires en un tour de bras. L'unique assistante qui trouve gr\195\162ce aux yeux de Veronica, \195\160 tel point que cette derni\195\168re s'en sert m\195\170me comme infuseur \195\160 th\195\169."
L31_1[1] = L32_1
L31_1[2] = L33_1
