L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_EPILOGUE"
L49_1 = "Une explosion a eu lieu dans cet immeuble, l\195\160-bas, alors j'ai suivi Momo. Qui aurait pu penser que ce serait notre bar ? Je n'oublierai jamais le regard de Momo \195\160 ce moment-l\195\160."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_1"
L50_1 = "Je viens \195\160 peine d'arriver ici et pourtant, j'ai l'impression de travailler dans ce bar depuis toujours. Mais je sais bien que je ne pourrais pas y rester \195\169ternellement..."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_2"
L51_1 = "Je dois mener \195\160 bien ma mission sacr\195\169e, j'en ai fait le serment. Mais alors, pourquoi est-ce que je continue d'h\195\169siter ? Le diable m'aurait-il s\195\169duite ?"
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_3"
L52_1 = "Si j'ai sign\195\169 un pacte avec le diable ? Absolument pas ! Je surveille juste ma cible, comme on m'a ordonn\195\169 de le faire !"
