L5_1 = "\236\157\140? \236\166\144\234\177\176\236\155\140 \235\179\180\236\157\184\235\139\164\234\179\160\226\128\166? \236\176\168, \236\176\169\234\176\129\237\149\152\236\167\128 \235\167\136\226\128\166! \236\157\180\234\177\180 \236\150\180\235\148\148\234\185\140\236\167\128\235\130\152 \236\158\132\235\172\180\235\139\164. \234\188\172\235\167\185\236\157\180\235\147\164\236\157\180\235\158\145 \236\150\180\236\154\184\235\166\172\235\138\148 \234\178\140 \236\166\144\234\177\176\236\154\184 \235\166\172 \236\151\134\236\158\150\235\130\152!"
