L30_1 = {}
L31_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REPLACER_CA_QUEEN_CHUSEOK@AB_UI_UNIT_VOICE_NKM_UNIT_REPLACER_CA_QUEEN_LOBBY_CAPTAIN"
L32_1 = "Il va y avoir de l'animation, ce soir."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_REPLACER_CA_QUEEN_CHUSEOK@AB_UI_UNIT_VOICE_NKM_UNIT_REPLACER_CA_QUEEN_LOBBY_CONNECT"
L33_1 = "Oh, te voil\195\160. Laisse-moi allumer une lanterne."
