L5_1 = "SI_SKIN_DESC_NKM_UNIT_DELTA_C_QUEEN_SUMMER"
L6_1 = "\195\128 l'origine, Delta Milk \195\169tait simplement une entreprise laiti\195\168re ordinaire qui fournissait du lait aux soldats.\nJusqu'au jour o\195\185 le responsable marketing remarqua une jeune femme au visage radieux, en train de siroter du lait au soleil.\nEnvo\195\187t\195\169 par son sourire onctueux, il d\195\169cida sans h\195\169siter de l'engager comme \195\169g\195\169rie promotionnelle.\nQuant \195\160 sa tenue... dieu sait pourquoi elle porte un maillot de bain.\n\n<color=#ffd34c>Tenez, soldats. Le lait, c'est la sant\195\169 ! Continuez \195\160 faire de votre mieux !</color>"
L4_1[1] = L5_1
L4_1[2] = L6_1
