L6_1 = "SI_SKIN_DESC_NKM_UNIT_S_POLICE_SOYEONG_SUMMER"
L7_1 = "Les policiers traquent les criminels \195\160 tout moment, o\195\185 qu'ils soient.\nY compris lors d'une soir\195\169e ou d'un cocktail \195\160 la plage.\nMais notre h\195\169ro\195\175ne de la vie ordinaire semble avoir n\195\169glig\195\169 une chose...\nC'est que son bikini n'est peut-\195\170tre pas assez r\195\169sistant pour retenir son \195\169lan.\n\n<color=#ffd34c>Ahaha... Bonjour ! Vous n'auriez pas vu le major par hasard ?</color>"
L5_1[1] = L6_1
L5_1[2] = L7_1
