L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_3_1_HM"
L4_1 = "Ne m'appelle pas comme \195\167a ! Je suis Kallen Kozuki !\n\n<color=#ffd34c>Affrontez Kallen Kozuki pour obtenir des rois d'\195\169checs et des \195\169quipements exclusifs.</color>"
