L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_2_INTERLUDE_5"
L6_1 = "Tu dois te souvenir, Mina... Quand tu ouvriras les yeux..."
