L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_2_INTERLUDE_4"
L7_1 = "Je me suis r\195\169veill\195\169e en sursaut. Cette \195\169cole m'est toujours aussi peu famili\195\168re."
