L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_2_INTERLUDE_2"
L9_1 = "C'est quoi cette blague ? Et regarde-moi cette tenue ! J'ai jamais sign\195\169 pour \195\167a, moi !"
