L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB_002_2_2_HM"
L12_1 = "Sais-tu pourquoi la neige est blanche ? Parce qu'elle a oubli\195\169 de quelle couleur elle \195\169tait. Et toi... connais-tu la tienne ?\n\n<color=#ffd34c>Affrontez C.C. pour obtenir des rois d'\195\169checs et des \195\169quipements exclusifs.</color>"
L10_1[1] = L11_1
