L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SWORD@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SWORD_LOBBY_TOUCH_NORMAL_1"
L35_1 = "Peu importe les m\195\169faits que vous avez commis, je les ferai dispara\195\174tre. Tant que vous accepterez de payer mes honoraires, bien entendu."
