L20_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_ARMOR_GET_01"
L21_1 = "Je t'attendais. On dirait bien que des d\195\169mons en avaient apr\195\168s ton \195\162me. Je m'en suis occup\195\169, alors ne t'aventure plus seul et reste \195\160 mes c\195\180t\195\169s."
