L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE5"
L50_1 = "Yanikka is the only Counter we can rely on. She has a strong sense of responsibility and is willing to put her life in danger."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_FLOOR_INTERLUDE6"
L51_1 = "As they all came out of hibernation, we were like rats in a trap. Whether we liked it or not, we had to rely on one another."
