L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_SAW_GET_01"
L8_1 = "My name is Yanikka Shirokova. As you can see, I'm a mixed beauty with cute fangs! Please call me Yanikka! You can put me to work right away! I'll do anything!"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
