L1_1[2] = L3_1
L2_1 = {}
L3_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_GET_01"
L4_1 = "Excuse me, but could you share your campfire with me? I've been wandering cold places for so long that I miss the warmth. What? You'll provide me with a cozy bed and a job too? Are you my savior?"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_CAPTAIN"
L5_1 = "As a paladin, I'll set an example! Although... I'm still just an apprentice."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_CONNECT"
L6_1 = "My bones are warm, so shall we get a move on?"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_CONNECT_LIFETIME"
L7_1 = "Let's get going, my savior."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_TOUCH_NORMAL_1"
L8_1 = "Is the company not doing so well? You can give me my salary with something else if you want. G-grapes? N-no, I do like them, but... are you sure you want to give me something so much more valuable than money? You're not going to regret this later, are you?"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_TOUCH_NORMAL_2"
L9_1 = "A paladin's pride is to help the weak. You're my savior, but since you're also weak, I'll protect you! You can count on me!"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_TOUCH_NORMAL_3"
L10_1 = "Devils are said to target the weakest part of the human mind. But don't worry! You may be more fragile than a baby, but your mind is stronger than anyone I know! Huh? What I said just hurt your feelings? O-oh, no..."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_TOUCH_NORMAL_4"
L11_1 = "Oh, this wound? I think I got it in a recent battle. It'll heal fast, so don't worry. Huh? You don't have to put a band-aid on it... Thank you. I feel a lot better now. Could you give me another next time I get injured?"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_TOUCH_LIFETIME_1"
L12_1 = "Whenever I'm in the dumps, just knowing that you're next to me is a huge relief. I thought I was protecting you, but... it's strange that you were protecting me."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_TOUCH_LIFETIME_2"
L13_1 = "I made some bread to give you. I put in a lot of expensive ingredients to express my gratitude for your hospitality... but do you think it's too much? Hehe..."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
