L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_LOBBY_CONNECT"
L13_1 = "Welcome back! Master was also waiting for you! *Cheerful chirps*"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_LOBBY_CONNECT_LIFETIME"
L14_1 = "Mm... I'm bored. Oh, you're back! What should we do today? *Scolding chirps* I-I'm just kidding, Master."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_LOBBY_TOUCH_NORMAL_1"
L15_1 = "What's a guardian angel, you ask? Mm... a soulmate that everyone on earth has? In a way that most people would understand is... Oh, right! Someone like a wife! *Scolding chirps* Huh? It's totally different?"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_LOBBY_TOUCH_NORMAL_2"
L16_1 = "Mr. Tweety is my grandmother's friend and my master. He's so cute, but is also strong enough to defeat a hundred devils with magic! *Scolding chirps* Hmm? But it's still true that you're cute."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_LOBBY_TOUCH_NORMAL_3"
L17_1 = "My grandmother is an archangel respected by all. And I inherited her powers, so I'm super strong as well! Although I faint after using one special move... Hehe. Still, it's really powerful, you know."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_LOBBY_TOUCH_NORMAL_4"
L18_1 = "My miracle has many effects, but the best of them is changing the taste of food! What do you think? Now the bread and water will have a refreshing minty taste! *Scolding chirps* Oww... Some people don't like this taste? That's ridiculous!"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_LOBBY_TOUCH_LIFETIME_1"
L19_1 = "Oh, it's time to take care of my feathers. Could you trim my feathers today instead of Master, darling? It's all right. Just be careful around the joints because he's sensitive down there! *Scolding chirps* Oh, you. Nothing's going to happen."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_CA_STREGA_YOO_NA_LOBBY_TOUCH_LIFETIME_2"
L20_1 = "Are you worried you might be late to work? Leave it to me! I'll fly you right over! Oh, right. I can't carry you on my back when I'm flapping my wings... That's it! Why don't you hang on to my legs then?"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
