L13_1 = {}
L14_1 = "SI_SKIN_DESC_NKM_UNIT_GAMECIRCLE_C_STAR_PARTY"
L15_1 = "Mi Rinae\226\152\133Starlight, l'\195\169lue de l'\195\137p\195\169e de l\195\169gende.\nSes talents l\195\169gendaires, forg\195\169s \195\160 travers d'innombrables aventures avec ses compagnons, sont ind\195\169niables.\nSi vous envisagez de la d\195\169fier, veillez \195\160 le faire avec respect.\nSinon, vous risquez de recevoir une cuisante correction de la part de cette v\195\169t\195\169rante.\n\n<color=#ffd34c>Tada ! Mi Rinae\226\152\133Starlight, \195\169veill\195\169e en tant qu'h\195\169ro\195\175ne ultime, est pr\195\170te \195\160 renverser la situation ! Eh oui, c'est mon mood du moment, h\195\169h\195\169.</color>"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
