L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_SKIN_DESC_NKM_UNIT_GAMECIRCLE_C_VIOLET_PARTY"
L17_1 = "Attir\195\169 par une m\195\169lodie envo\195\187tante, vous vous retrouvez perdu dans une for\195\170t inconnue.\nComme sous l'effet d'un sort, vous arrivez finalement devant la maison d'une sorci\195\168re.\nSi vous craignez d'\195\170tre d\195\169vor\195\169, rassurez-vous :\nla sorci\195\168re pr\195\169f\195\168re offrir de d\195\169licieux biscuits aux visiteurs \195\169gar\195\169s.\n\n<color=#ffd34c>Vous... Vous avez besoin de moi ? En tant que sorci\195\168re !</color>"
L15_1[1] = L16_1
L15_1[2] = L17_1
