L32_1 = "SI_UNIT_DESC_NKM_UNIT_ACADEMY_CA_TWINTAIL"
L33_1 = "Une d\195\169fenseuse de m\195\170l\195\169e qui inflige des affaiblissements aux ennemis pour soutenir ses alli\195\169s au combat"
