L41_1 = {}
L42_1 = "SI_SKIN_DESC_NKM_UNIT_CA_YOO_MI_NA_SPECIAL"
L43_1 = "La fin du monde. Les derniers instants du monde o\195\185 m\195\170me le temps s'est fig\195\169.\nEn se tenant chaud l'un contre l'autre \195\160 travers l'interminable hiver.\nVous vous \195\170tes jur\195\169 de faire face \195\160 un destin cruel.\nCar elle est votre louve, et vous \195\170tes son ma\195\174tre.\nVous \195\170tes des \195\170tres pr\195\169cieux et irrempla\195\167ables l'un pour pour l'autre.\n\n<color=#ffd34c>Ce n\226\128\153est pas parce qu\226\128\153on est fort qu\226\128\153on survit. C\226\128\153est parce qu'on survit qu'on est fort.</color>"
L41_1[1] = L42_1
