L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_GET_01"
L11_1 = "I, Esterosa de Chevalier, Captain of the Zodiac Knights. Once more, I shall become your sword and shield, to protect the innocent. This vow shall never waver, so long as you and I still draw breath."
L9_1[1] = L10_1
