L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_CONNECT"
L13_1 = "Standing by. All clear. Awaiting your orders."
