L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_SKIN_DESC_NKM_UNIT_REAPER_SA_COMMANDER_SUMMER"
L51_1 = "Cette soi-disant r\195\169union secr\195\168te \195\169tait en fait un pr\195\169texte pour faire une pause.\nLors de votre arriv\195\169e sur l'\195\174le o\195\185 vous avez \195\169t\195\169 invit\195\169, elle dormait d\195\169j\195\160, berc\195\169e par le bruit des vagues.\nCe lieu \195\169tait cens\195\169 n\226\128\153\195\170tre que pour vous deux, mais vous sentez des regards gla\195\167ants braqu\195\169s sur vous...\nMais qu'importe. Ce genre de fille, \195\167a se m\195\169rite.\n\n<color=#ffd34c>Vu comme vous me fixez, c'est que je dois \195\170tre votre style. Je me trompe ?</color>"
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
