L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_UNIT_DESC_NKM_UNIT_ESPR_CA_KNIGHT"
L15_1 = "Une unit\195\169 \195\160 distance qui lance de puissantes attaques \195\160 chaque fois qu'un ennemi meurt"
