L17_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_RAS_MA_TOWER_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_RAS_MA_TOWER_LOBBY_CONNECT"
L18_1 = "Do I really have to go out today? I'm always waiting just for you. Don't you... wait for me too, Daddy?"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_RAS_MA_TOWER_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_RAS_MA_TOWER_LOBBY_CONNECT_LIFETIME"
L19_1 = "It's dangerous outside. The mean Wolf might hurt you, Daddy. So... stay with me today? Hmm?"
