L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_4_INTERLUDE2"
L12_1 = "Les conditions pour transf\195\169rer un prisonnier sur un autre navire \195\169taient plut\195\180t strictes.\nPremi\195\168rement, il fallait \195\170tre une personne ayant d\195\169j\195\160 per\195\167u des primes \195\160 Front Bay pendant une certaine p\195\169riode.\nDeuxi\195\168mement, \195\170tre une TASKFORCE officiellement autoris\195\169e.\nTroisi\195\168mement, \195\170tre un pirate."
L10_1[1] = L11_1
