L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_SS_OMEN_5_1_10"
L41_1 = "Chiens de Tindalos"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_5_1_10"
L42_1 = "Le Lac de la connaissance est \195\160 la fois Un et Tout. Tout et Un.\nAu sein de leur groupe, un amas d'informations sacr\195\169es, sommeillent de multiples divinit\195\169s."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
