L36_1 = "SI_EPISODE_DESC_1_SS_OMEN_6"
L37_1 = "D\195\169sirer obtenir ce que l\226\128\153on n\226\128\153a pas est l\226\128\153essence m\195\170me de toute chose. Quand bien m\195\170me cela finirait par te mener \195\160 ta perte."
