L2_1 = "SI_SKILL_DESC_OPR_REPLACER_LOOK"
L3_1 = "Conf\195\168re <color=#ffd34c>ESQ infaillible\226\151\135</color> \195\160 <color=#ffd34c>toutes les unit\195\169s ennemies \195\160 l'exception des boss</color> pendant <color=#ffd34c>12 s</color>. Conf\195\168re \195\160 <color=#ffd34c>toutes les unit\195\169s alli\195\169es</color> <color=#ffd34c>ESQ infaillible\226\151\135</color> et <color=#ffd34c>{stat1} +{factor1} %, {stat2} +{value2} %</color> pendant <color=#ffd34c>15 s</color>. Cet effet <color=#ffd34c>ne peut pas \195\170tre annul\195\169</color>."
