L20_1 = "SI_SKILL_DESC_OPR_CREW"
L21_1 = "Conf\195\168re <color=#ffd34c>{stat1} +{factor1}\194\160% </color> \195\160 <color=#ffd34c>toutes les unit\195\169s alli\195\169s</color> pendant <color=#ffd34c>{time}\194\160s</color>. Conf\195\168re [#UNIT_OPR_CREW_STRIKER#] aux <color=#ffd34c>attaquants alli\195\169s</color> et [#UNIT_OPR_CREW_DEFENDER#] aux <color=#ffd34c>d\195\169fenseurs alli\195\169s</color> pendant la dur\195\169e du bonus. Cet effet <color=#ffd34c>ne peut pas \195\170tre annul\195\169</color>."
