L43_1 = {}
L44_1 = "SI_EXPLORE_EVENT_RESULTDESC2_80065_2"
L45_1 = "Vous vous \195\170tes \195\169loign\195\169 en esp\195\169rant que lui aussi, un jour... trouverait enfin la paix."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EXPLORE_EVENT_MAINDESC_80066_1"
L46_1 = "L'\195\169cole.\nUne institution d\195\169di\195\169e \195\160 l'\195\169ducation des \195\169l\195\168ves.\nSous l'autorit\195\169 d'un seul ma\195\174tre, de nombreux \195\169tudiants s'entra\195\174nent \195\160 tuer.\nCar seuls les plus forts seront aptes \195\160 assimiler les agents de qualit\195\169 sup\195\169rieure.\nCar seuls les plus forts... seront dignes d'\195\170tre les \195\169lus de l'humanit\195\169 du nouveau monde."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EXPLORE_EVENT_MAINDESC_80066_2"
