L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EXPLORE_EVENT_RESULTDESC2_80066_4"
L12_1 = "Vous avez r\195\169ussi \195\160 \195\169chapper de justesse \195\160 l'attaque de la Reine des substituts.\nCombien de temps avez-vous couru, \195\169perdu ?\nAlors que vous repreniez votre souffle en jetant un regard en arri\195\168re, il ne restait plus rien."
