L42_1 = "Lui tenir la main"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EXPLORE_EVENT_RESULTDESC2_80069_1"
L43_1 = "Depuis son enfance, la jeune fille n'accordait sa confiance qu'\195\160 ceux qui avaient partag\195\169 la m\195\170me douleur qu'elle.\nVous avez tendu la main, r\195\169solu \195\160 devenir, pour elle, la seule personne sur laquelle elle puisse enfin compter."
