L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP15_ACT1_INTERLUDE_3"
L6_1 = "L'arbre dor\195\169 est immuable. M\195\170me le temps y demeure immobile. Ceux qui s'avancent vers l'avenir ne sont pas dignes d'y faire face."
L4_1[1] = L5_1
